CREATE TABLE workspace_members (user_id TEXT PRIMARY KEY, role TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE workspace_documents (key TEXT PRIMARY KEY, data TEXT NOT NULL, revision INTEGER NOT NULL, actor TEXT NOT NULL, updated_at TEXT NOT NULL, operation TEXT NOT NULL UNIQUE, reason TEXT NOT NULL);
CREATE TABLE workspace_versions (sequence BIGSERIAL PRIMARY KEY, key TEXT NOT NULL, data TEXT NOT NULL, revision INTEGER NOT NULL, actor TEXT NOT NULL, updated_at TEXT NOT NULL, operation TEXT NOT NULL UNIQUE, reason TEXT NOT NULL, UNIQUE(key,revision));
CREATE INDEX workspace_versions_key ON workspace_versions(key,revision DESC);
CREATE TABLE workspace_access (sequence BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, at TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL);
CREATE OR REPLACE FUNCTION workspace_version_append() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO workspace_versions(key,data,revision,actor,updated_at,operation,reason) VALUES(NEW.key,NEW.data,NEW.revision,NEW.actor,NEW.updated_at,NEW.operation,NEW.reason); RETURN NEW; END $$;
CREATE TRIGGER workspace_document_insert AFTER INSERT OR UPDATE ON workspace_documents FOR EACH ROW EXECUTE FUNCTION workspace_version_append();
CREATE OR REPLACE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical audit is immutable'; END $$;
CREATE TRIGGER workspace_versions_no_change BEFORE UPDATE OR DELETE ON workspace_versions FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TABLE workspace_write_checks (operation TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid=1));
CREATE TABLE professional_profiles (user_id TEXT PRIMARY KEY, display_name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', profession TEXT NOT NULL DEFAULT 'unassigned', active INTEGER NOT NULL DEFAULT 1, rpps TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE care_teams (id TEXT PRIMARY KEY, label TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE professional_teams (user_id TEXT NOT NULL, team_id TEXT NOT NULL, valid_from TEXT NOT NULL, valid_until TEXT, PRIMARY KEY(user_id,team_id));
CREATE TABLE stay_teams (stay_id TEXT NOT NULL, team_id TEXT NOT NULL, valid_from TEXT NOT NULL, valid_until TEXT, PRIMARY KEY(stay_id,team_id));
CREATE TABLE professional_access_log (sequence BIGSERIAL PRIMARY KEY, at TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, result TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '');
CREATE INDEX professional_access_actor ON professional_access_log(actor,sequence DESC);
CREATE INDEX professional_access_target ON professional_access_log(target,sequence DESC);
CREATE TABLE professional_policy_revision (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 1);
INSERT INTO professional_policy_revision(id,revision) VALUES(1,1);
CREATE TABLE file_scopes (hash TEXT NOT NULL, document_key TEXT NOT NULL, PRIMARY KEY(hash,document_key));
CREATE TABLE access_migrations (id TEXT PRIMARY KEY);
CREATE OR REPLACE FUNCTION bump_professional_policy() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE professional_policy_revision SET revision=revision+1 WHERE id=1; RETURN NEW; END $$;
CREATE TRIGGER professional_profiles_policy AFTER INSERT OR UPDATE ON professional_profiles FOR EACH ROW EXECUTE FUNCTION bump_professional_policy();
CREATE TRIGGER professional_teams_policy AFTER INSERT OR UPDATE ON professional_teams FOR EACH ROW EXECUTE FUNCTION bump_professional_policy();
CREATE TRIGGER stay_teams_policy AFTER INSERT OR UPDATE ON stay_teams FOR EACH ROW EXECUTE FUNCTION bump_professional_policy();
CREATE TRIGGER care_teams_policy AFTER UPDATE ON care_teams FOR EACH ROW EXECUTE FUNCTION bump_professional_policy();
CREATE TRIGGER professional_access_no_change BEFORE UPDATE OR DELETE ON professional_access_log FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TABLE questionnaire_invitations (token_hash TEXT PRIMARY KEY, stay_id TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, used_at TEXT);
CREATE INDEX questionnaire_invitations_stay ON questionnaire_invitations(stay_id);
CREATE TABLE auth_users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE auth_sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES auth_users(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX auth_sessions_user ON auth_sessions(user_id);
CREATE TABLE auth_attempts (id BIGSERIAL PRIMARY KEY, identity_hash TEXT NOT NULL, at TEXT NOT NULL, success INTEGER NOT NULL);
CREATE INDEX auth_attempts_identity ON auth_attempts(identity_hash,at);
CREATE TABLE auth_audit (id BIGSERIAL PRIMARY KEY, at TEXT NOT NULL, user_id TEXT NOT NULL, action TEXT NOT NULL);
CREATE TRIGGER auth_audit_no_change BEFORE UPDATE OR DELETE ON auth_audit FOR EACH ROW EXECUTE FUNCTION immutable_audit();
